     1→import { type Difficulty } from '../types/GameMode';
     2→
     3→// API 기본 URL (환경에 따라 자동 감지)
     4→const API_BASE_URL = import.meta.env.DEV
     5→  ? 'http://localhost:5173'
     6→  : import.meta.env.VITE_API_BASE_URL || 'https://ddong-avoid-game.vercel.app';
     7→
     8→export interface LeaderboardEntry {
     9→  userId: string;
    10→  userName: string;
    11→  score: number;
    12→  rank: number;
    13→}
    14→
    15→export interface SubmitScoreResponse {
    16→  success: boolean;
    17→  isNewRecord: boolean;
    18→  previousScore: number | null;
    19→  newScore: number;
    20→  rank: number | null;
    21→  message?: string;
    22→}
    23→
    24→export interface LeaderboardResponse {
    25→  success: boolean;
    26→  difficulty: string;
    27→  leaderboard: LeaderboardEntry[];
    28→  currentUserRank: {
    29→    rank: number;
    30→    score: number;
    31→  } | null;
    32→  totalEntries: number;
    33→}
    34→
    35→/**
    36→ * 사용자 ID 생성 또는 조회 (localStorage 사용)
    37→ */
    38→export function getUserId(): string {
    39→  let userId = localStorage.getItem('userId');
    40→
    41→  if (!userId) {
    42→    // UUID v4 형식으로 생성
    43→    userId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    44→      const r = Math.random() * 16 | 0;
    45→      const v = c === 'x' ? r : (r & 0x3 | 0x8);
    46→      return v.toString(16);
    47→    });
    48→    localStorage.setItem('userId', userId);
    49→  }
    50→
    51→  return userId;
    52→}
    53→
    54→/**
    55→ * 사용자 이니셜 조회
    56→ */
    57→export function getUserInitials(): string | null {
    58→  return localStorage.getItem('userInitials');
    59→}
    60→
    61→/**
    62→ * 사용자 이니셜 저장
    63→ * @param initials 3자리 영어 대문자 (예: "ABC")
    64→ */
    65→export function setUserInitials(initials: string): boolean {
    66→  // 검증: 정확히 3자리, 영어 대문자만
    67→  const validation = /^[A-Z]{3}$/;
    68→  if (!validation.test(initials)) {
    69→    return false;
    70→  }
    71→
    72→  localStorage.setItem('userInitials', initials);
    73→  return true;
    74→}
    75→
    76→/**
    77→ * 이니셜이 설정되어 있는지 확인
    78→ */
    79→export function hasUserInitials(): boolean {
    80→  const initials = getUserInitials();
    81→  return initials !== null && /^[A-Z]{3}$/.test(initials);
    82→}
    83→
    84→/**
    85→ * 점수 제출
    86→ */
    87→export async function submitScore(
    88→  score: number,
    89→  difficulty: Difficulty,
    90→  initials: string
    91→): Promise<SubmitScoreResponse> {
    92→  const userId = getUserId();
    93→
    94→  // 이니셜 검증
    95→  if (!/^[A-Z]{3}$/.test(initials)) {
    96→    throw new Error('Invalid initials: must be 3 uppercase letters');
    97→  }
    98→
    99→  // 🚧 로컬 개발 모드: Mock 데이터 반환 (Vercel Functions가 없을 때)
   100→  if (import.meta.env.DEV) {
   101→    console.warn('⚠️ DEV MODE: Using mock data. Deploy to Vercel to test real API.');
   102→
   103→    // 1초 지연으로 실제 API 호출처럼 보이게
   104→    await new Promise(resolve => setTimeout(resolve, 1000));
   105→
   106→    // Mock 응답
   107→    return {
   108→      success: true,
   109→      isNewRecord: true,
   110→      previousScore: Math.max(0, score - 100),
   111→      newScore: score,
   112→      rank: Math.floor(Math.random() * 100) + 1, // 랜덤 순위 1-100
   113→    };
   114→  }
   115→
   116→  // 🚀 프로덕션: 실제 API 호출
   117→  const response = await fetch(`${API_BASE_URL}/api/leaderboard/submit`, {
   118→    method: 'POST',
   119→    headers: {
   120→      'Content-Type': 'application/json',
   121→    },
   122→    body: JSON.stringify({
   123→      userId,
   124→      userName: initials, // 이니셜을 userName으로 전송
   125→      score,
   126→      difficulty,
   127→    }),
   128→  });
   129→
   130→  if (!response.ok) {
   131→    const error = await response.json();
   132→    throw new Error(error.error || 'Failed to submit score');
   133→  }
   134→
   135→  return response.json();
   136→}
   137→
   138→/**
   139→ * 리더보드 조회
   140→ */
   141→export async function getLeaderboard(
   142→  difficulty: Difficulty,
   143→  limit: number = 100
   144→): Promise<LeaderboardResponse> {
   145→  const userId = getUserId();
   146→
