import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  if (req.method !== 'POST') {
    return new Response(JSON.stringify({ error: 'Method not allowed' }), {
      status: 405,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  try {
    // 유저 JWT로 클라이언트 생성 (RLS 적용)
    const authHeader = req.headers.get('Authorization');
    const supabaseClient = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
      { global: { headers: { Authorization: authHeader ?? '' } } }
    );

    // JWT에서 유저 정보 추출
    const { data: { user }, error: authError } = await supabaseClient.auth.getUser();
    if (authError || !user) {
      return new Response(JSON.stringify({ error: 'Unauthorized' }), {
        status: 401,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }

    const { score, difficulty, initials } = await req.json();

    // 입력값 검증
    if (typeof score !== 'number' || score < 0) {
      return new Response(JSON.stringify({ error: 'Invalid score' }), {
        status: 400,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }

    const validDifficulties = ['easy', 'normal', 'hard', 'extreme'];
    if (!validDifficulties.includes(difficulty)) {
      return new Response(JSON.stringify({ error: 'Invalid difficulty' }), {
        status: 400,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }

    // 서비스 롤 클라이언트 (RLS 우회하여 쓰기)
    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    );

    // 이니셜 저장 (있는 경우)
    if (initials && /^[A-Z]{3}$/.test(initials)) {
      await supabaseAdmin
        .from('profiles')
        .update({ initials })
        .eq('id', user.id);
    }

    // 기존 점수 조회
    const { data: existing } = await supabaseAdmin
      .from('leaderboard')
      .select('score')
      .eq('user_id', user.id)
      .eq('difficulty', difficulty)
      .single();

    const previousScore = existing?.score ?? null;
    const isNewRecord = previousScore === null || score > previousScore;

    // 더 높은 점수만 upsert
    if (isNewRecord) {
      await supabaseAdmin
        .from('leaderboard')
        .upsert({
          user_id: user.id,
          difficulty,
          score,
          updated_at: new Date().toISOString(),
        }, { onConflict: 'user_id,difficulty' });
    }

    // 현재 순위 조회
    const { count } = await supabaseAdmin
      .from('leaderboard')
      .select('*', { count: 'exact', head: true })
      .eq('difficulty', difficulty)
      .gt('score', score);

    const rank = (count ?? 0) + 1;

    return new Response(
      JSON.stringify({ success: true, isNewRecord, previousScore, newScore: score, rank }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );

  } catch (error) {
    return new Response(
      JSON.stringify({ error: 'Internal server error', details: String(error) }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
});

