// API 기본 URL (환경에 따라 자동 감지)
const API_BASE_URL = import.meta.env.DEV
  ? 'http://localhost:5173'
  : import.meta.env.VITE_API_BASE_URL || 'https://ddong-avoid-game.vercel.app';

