        fontSize: '48px',
        color: '#ff0000',
        fontStyle: 'bold',
        stroke: '#000000',
        strokeThickness: 6
      }).setOrigin(0.5).setDepth(200);

      // 최종 점수
      this.add.text(200, 150, `점수: ${this.score}`, {
        fontSize: '32px',
        color: '#ffffff',
        fontStyle: 'bold',
        stroke: '#000000',
        strokeThickness: 4
      }).setOrigin(0.5).setDepth(200);

      // 새 기록 메시지
      this.add.text(200, 200, '🎉 개인 신기록 🎉', {
        fontSize: '28px',
        color: '#FFD700',
        fontStyle: 'bold',
