update() {
  if (!this.gameOver) {
    this.player.update();

    const now = Date.now();

    // 레이어 1: Date.now() 기반 점수 계산 (timeScale 조작 무력화)
    const elapsed = now - this.lastScoreTime;
    if (elapsed >= 100) {
      const points = Math.floor(elapsed / 100);
      this.lastScoreTime = now - (elapsed % 100); // 나머지 시간 이월
      this.updateScore(points);
    }

    // 레이어 2: timeScale 이상 감지 (5초마다 체크)
    if (now - this.lastCheatCheckTime >= 5000) {
      const realElapsed = now - this.gameStartTime;
      const gameElapsed = this.time.now; // Phaser 내부 시간 (timeScale 영향 받음)
      const ratio = gameElapsed / realElapsed;

      // 정상 비율은 ~1.0, 0.5 미만이면 게임 시간이 실제 시간의 절반 이하 → 조작 의심
      if (ratio < 0.5) {
        console.warn('[Anti-cheat] timeScale 조작 감지:', ratio.toFixed(2));
        this.handleCheatDetected();
        return;
      }
      this.lastCheatCheckTime = now;
    }
  }
}

private handleCheatDetected() {
  this.gameOver = true;
  this.physics.pause();
  this.sound.stopAll();

  this.add.rectangle(200, 300, 400, 600, 0x000000, 0.8).setDepth(500);
  this.add.text(200, 280, '⚠️ 비정상적인 플레이가\n감지되었습니다', {
    fontSize: '22px',
    color: '#ff4444',
    fontStyle: 'bold',
    stroke: '#000',
    strokeThickness: 4,
    align: 'center',
  }).setOrigin(0.5).setDepth(501);

  this.time.delayedCall(3000, () => {
    this.scene.start('ModeSelectScene');
  });
}

private spawnPoop() {
  if (this.gameOver) return;

  // 난이도에 따른 개수만큼 생성 (각각 다른 높이에서)
  const poopCount = this.difficultyConfig.poopCount;
  for (let i = 0; i < poopCount; i++) {
    // 💩이 화면 전체에서 생성되도록 (💩 크기 15를 고려해서 양쪽 여유)
    const x = Phaser.Math.Between(15, 385);
    const y = Phaser.Math.Between(-200, -20);
    const poop = new Poop(this, x, y, this.difficultyLevel, this.difficulty);
    this.poops.add(poop, true);

    // 명시적으로 velocity 설정 (그룹 추가 후)
    if (poop.body) {
      // 난이도 기본 속도 + 시간에 따른 증가
      const fallSpeed = this.difficultyConfig.baseSpeed + (this.difficultyLevel * 40);
      poop.body.velocity.y = fallSpeed;
    }
  }

}

private spawnStars() {
  if (this.gameOver) return;

  // 별 6개를 랜덤 위치에 생성
  const starCount = 6;
  for (let i = 0; i < starCount; i++) {
    const x = Phaser.Math.Between(15, 385);

