        fontSize: '48px',
        color: '#ff0000',
        fontStyle: 'bold',
        stroke: '#000000',
        strokeThickness: 6
      }).setOrigin(0.5).setDepth(200);

      // 최종 점수
      this.add.text(200, 260, `점수: ${this.score}`, {
