  1→import { type Difficulty } from '../types/GameMode';
  2→import { getCurrentUserId } from './auth';
  3→import { supabase } from './supabase';
  4→
  5→export interface LeaderboardEntry {
  6→  userId: string;
  7→  userName: string;
  8→  score: number;
  9→  rank: number;
 10→}
 11→
 12→export interface SubmitScoreResponse {
 13→  success: boolean;
 14→  isNewRecord: boolean;
 15→  previousScore: number | null;
 16→  newScore: number;
 17→  rank: number | null;
 18→  message?: string;
 19→}
 20→
 21→export interface LeaderboardResponse {
 22→  success: boolean;
 23→  difficulty: string;
 24→  leaderboard: LeaderboardEntry[];
 25→  currentUserRank: {
 26→    rank: number;
 27→    score: number;
 28→  } | null;
 29→  totalEntries: number;
 30→}
 31→
 32→/**
 33→ * 사용자 ID 조회 (Supabase Auth 기반)
 34→ */
 35→export async function getUserId(): Promise<string> {
 36→  return getCurrentUserId();
 37→}
 38→
 39→/**
 40→ * 사용자 이니셜 조회
 41→ */
 42→export function getUserInitials(): string | null {
 43→  return localStorage.getItem('userInitials');
 44→}
 45→
 46→/**
 47→ * 사용자 이니셜 저장
 48→ * @param initials 3자리 영어 대문자 (예: "ABC")
 49→ */
 50→export function setUserInitials(initials: string): boolean {
 51→  const validation = /^[A-Z]{3}$/;
 52→  if (!validation.test(initials)) {
 53→    return false;
 54→  }
 55→
 56→  localStorage.setItem('userInitials', initials);
 57→  return true;
 58→}
 59→
 60→/**
 61→ * 이니셜이 설정되어 있는지 확인
 62→ */
 63→export function hasUserInitials(): boolean {
 64→  const initials = getUserInitials();
 65→  return initials !== null && /^[A-Z]{3}$/.test(initials);
 66→}
 67→
 68→export interface ScoreVerificationData {
 69→  gameStartTime: number;
 70→  gameEndTime: number;
 71→  goldCollected: number;
 72→  diamondCollected: number;
 73→  topazCollected: number;
 74→  rainbowCollected: number;
 75→}
 76→
 77→/**
 78→ * 점수 제출
 79→ */
 80→export async function submitScore(
 81→  score: number,
 82→  difficulty: Difficulty,
 83→  initials: string,
 84→  verificationData: ScoreVerificationData
 85→): Promise<SubmitScoreResponse> {
 86→  if (!/^[A-Z]{3}$/.test(initials)) {
 87→    throw new Error('Invalid initials: must be 3 uppercase letters');
 88→  }
 89→
 90→  const { data, error } = await supabase.functions.invoke('leaderboard-submit', {
 91→    body: {
 92→      score,
 93→      difficulty,
 94→      userName: initials,
 95→      verification: verificationData,
 96→    },
 97→  });
 98→
 99→  if (error) {
100→    throw new Error(error.message || 'Failed to submit score');
101→  }
102→
103→  return data as SubmitScoreResponse;
104→}
105→
106→/**
107→ * 리더보드 조회
108→ */
109→export async function getLeaderboard(
110→  difficulty: Difficulty,
111→  limit: number = 100
112→): Promise<LeaderboardResponse> {
113→  const { data, error } = await supabase.functions.invoke('leaderboard-top', {
114→    body: { difficulty, limit },
115→  });
116→
117→  if (error) {
118→    throw new Error(error.message || 'Failed to fetch leaderboard');
119→  }
120→
121→  return data as LeaderboardResponse;
122→}
