  24→  private stars!: Phaser.Physics.Arcade.Group;
  25→  private items!: Phaser.Physics.Arcade.Group;
  26→  private score: number = 0;
  27→  private scoreText!: Phaser.GameObjects.Text;
  28→  private highScore: number = 0;
  29→  private highScoreText!: Phaser.GameObjects.Text;
  30→  private gameOver: boolean = false;
  31→  private spawnTimer!: Phaser.Time.TimerEvent;
  32→  private difficultyLevel: number = 2;
  33→  private bgMusic!: Phaser.Sound.BaseSound;
  34→  private gameMode: GameMode = GameMode.CLASSIC;
  35→  private difficulty: Difficulty = Difficulty.HARD;
  36→  private difficultyConfig!: DifficultyConfig;
  37→  private lastGoldPoopScore: number = 0;
  38→  private lastDiamondPoopScore: number = 0;
  39→  private lastTopazPoopScore: number = 0;
  40→  private feverTopazTimer!: Phaser.Time.TimerEvent;
  41→  private lastRainbowPoopScore: number = 0;
  42→  // 점수 검증용 데이터
  43→  private gameStartTime: number = 0;
  44→  private phaserStartTime: number = 0; // 씬 시작 시 Phaser 내부 시간 (재시작 시에도 정확한 delta 계산용)
  45→  private lastScoreTime: number = 0;   // Date.now() 기반 점수용
  46→  private lastCheatCheckTime: number = 0; // timeScale 감지용
  47→  private goldCollected: number = 0;
  48→  private diamondCollected: number = 0;
  49→  private topazCollected: number = 0;
  50→  private rainbowCollected: number = 0;
  51→  // 피버 타임 관련
  52→  private isFeverTime: boolean = false; // 피버 타임 활성화 여부
  53→  private feverTimeRemaining: number = 0; // 피버 타임 남은 시간 (ms)
  54→  private feverTimeTimer!: Phaser.Time.TimerEvent; // 피버 타임 카운트다운 타이머
  55→  private feverTimeUITexts: Phaser.GameObjects.Text[] = []; // 피버 타임 UI 텍스트 (각 글자별)
  56→  private feverTimeColorOffset: number = 0; // 무지개 색상 회전 오프셋
  57→  private feverTimeColorTimer!: Phaser.Time.TimerEvent; // 색상 애니메이션 타이머
  58→  private lastFeverTimeScore: number = 0; // 마지막 피버 타임 발동 점수
  59→  private isMinerPlayer: boolean = false; // 광부 캐릭터 선택 여부
  60→  private isMaehwaPlayer: boolean = false; // 매화검수 캐릭터 선택 여부
  61→
  62→  constructor() {
  63→    super('GameScene');
  64→  }
  65→
  66→  init(data: { gameMode?: GameMode; difficulty?: Difficulty }) {
  67→    // 게임 재시작 시 점수 관련 변수 초기화
  68→    this.score = 0;
  69→    this.gameOver = false;
  70→    this.difficultyLevel = 2;
  71→    this.lastGoldPoopScore = 0;
  72→    this.lastDiamondPoopScore = 0;
  73→    this.lastTopazPoopScore = 0;
  74→    this.lastRainbowPoopScore = 0;
  75→    this.gameStartTime = Date.now();
  76→    this.phaserStartTime = 0; // create()에서 설정
  77→    this.lastScoreTime = Date.now();
  78→    this.lastCheatCheckTime = Date.now();
  79→    this.goldCollected = 0;
  80→    this.diamondCollected = 0;
  81→    this.topazCollected = 0;
  82→    this.rainbowCollected = 0;
  83→    // 피버 타임 초기화
  84→    this.isFeverTime = false;
  85→    this.feverTimeRemaining = 0;
  86→    this.lastFeverTimeScore = 0;
  87→    this.isMinerPlayer = false; // Initialize to false
  88→    this.isMaehwaPlayer = false; // Initialize to false
  89→
  90→    // Randomly select special player for Classic mode
  91→    if (data.gameMode === GameMode.CLASSIC) {
  92→      if (Math.random() < 0.2) { // 20% 확률로 특수 캐릭터
  93→        if (Math.random() < 0.2) { // 그 중 20% 확률로 매화검수 (전체 4%)
  94→          this.isMaehwaPlayer = true;
  95→        } else { // 나머지 80% 확률로 광부 (전체 16%)
  96→          this.isMinerPlayer = true;
  97→        }
  98→      }
  99→    }
 100→
 101→    // ModeSelectScene/DifficultySelectScene으로부터 게임 모드와 난이도를 받음
 102→    if (data.gameMode) {
 103→      this.gameMode = data.gameMode;
 104→      // console.log('Game Mode:', this.gameMode);
 105→    }
 106→    if (data.difficulty) {
 107→      this.difficulty = data.difficulty;
 108→      // console.log('Difficulty:', this.difficulty);
 109→      localStorage.setItem('lastPlayedDifficulty', data.difficulty);
 110→    }
 111→
 112→    // 난이도 설정 찾기
 113→    const config = DIFFICULTIES.find(d => d.difficulty === this.difficulty);
 114→    if (config) {
 115→      this.difficultyConfig = config;
 116→    } else {
 117→      // 기본값은 HARD
 118→      this.difficultyConfig = DIFFICULTIES.find(d => d.difficulty === Difficulty.HARD)!;
 119→    }
 120→  }
 121→
 122→  preload() {
 123→    // DifficultySelectScene에서 미리 로딩됨. 캐시에 없을 경우에만 fallback 로딩.
 124→
