 129→        this.load.image('background3', 'assets/backgrounds/background3.webp');
 130→      } else if ((this.difficulty === Difficulty.HARD || this.difficulty === Difficulty.EXTREME) && !this.textures.exists('background')) {
 131→        this.load.image('background', 'assets/backgrounds/background.webp');
 132→      }
 133→      if (this.difficulty === Difficulty.EXTREME && isChristmasSeason() && !this.textures.exists('xmas_background')) {
 134→        this.load.image('xmas_background', 'assets/backgrounds/xmas_background.webp');
