 758→   */
 759→  private checkFeverTime(score: number) {
 760→    if (score < FEVER_TIME_CONFIG.firstTriggerScore) return;
 761→
 762→    // 첫 피버 타임 또는 반복 간격 체크
 763→    let nextFeverScore: number;
 764→    const secondTrigger = FEVER_TIME_CONFIG.firstTriggerScore + FEVER_TIME_CONFIG.repeatInterval;
 765→
 766→    if (score < secondTrigger) {
 767→      nextFeverScore = FEVER_TIME_CONFIG.firstTriggerScore;
 768→    } else {
 769→      const feverIndex = Math.floor((score - FEVER_TIME_CONFIG.firstTriggerScore) / FEVER_TIME_CONFIG.repeatInterval);
 770→      nextFeverScore = FEVER_TIME_CONFIG.firstTriggerScore + feverIndex * FEVER_TIME_CONFIG.repeatInterval;
 771→    }
 772→
 773→    if (score >= nextFeverScore && this.lastFeverTimeScore < nextFeverScore) {
 774→      this.startFeverTime();
 775→      this.lastFeverTimeScore = nextFeverScore;
 776→    }
 777→  }
