      const charIcon = characterIcons[entry.characterType ?? 'chibi'] ?? '👶';

      const rankText = `${entry.rank}`.padEnd(6, ' ');
      const nameText = `${charIcon}${entry.userName}`.padEnd(10, ' ');
      const scoreText = entry.score.toString().padStart(6, ' ');

      const text = this.add.text(
        200,
        y,
        `${rankText}${nameText}${scoreText}`,
        {
          fontSize: '16px',
          color: color,
          fontFamily: 'monospace',
          stroke: '#000',
          strokeThickness: 3
        }
      ).setOrigin(0.5);

      this.leaderboardTexts.push(text);
