139→  private setupScrollInput() {
140→    // 터치/마우스 드래그 스크롤
141→    this.input.on('pointerdown', (pointer: Phaser.Input.Pointer) => {
142→      if (pointer.y > 70 && pointer.y < 540) {
143→        this.isDragging = true;
144→        this.dragStartY = pointer.y;
145→        this.dragStartScrollY = this.scrollY;
146→      }
147→    });
148→
149→    this.input.on('pointermove', (pointer: Phaser.Input.Pointer) => {
150→      if (!this.isDragging) return;
151→      const deltaY = this.dragStartY - pointer.y;
152→      this.scrollY = Phaser.Math.Clamp(
153→        this.dragStartScrollY + deltaY,
154→        0,
155→        this.maxScrollY,
156→      );
157→      this.scrollContainer.y = 70 - this.scrollY;
158→    });
159→
160→    this.input.on('pointerup', () => {
161→      this.isDragging = false;
162→    });
163→
164→    // 마우스 휠 스크롤
165→    this.input.on('wheel', (_pointer: Phaser.Input.Pointer, _gameObjects: Phaser.GameObjects.GameObject[], _deltaX: number, deltaY: number) => {
166→      this.scrollY = Phaser.Math.Clamp(
167→        this.scrollY + deltaY * 0.5,
168→        0,
169→        this.maxScrollY,
170→      );
171→      this.scrollContainer.y = 70 - this.scrollY;
172→    });
173→  }
