182→      fontStyle: 'bold',
183→    }).setOrigin(0.5).setDepth(10);
184→
185→    button.setInteractive({ useHandCursor: true });
186→    text.setInteractive({ useHandCursor: true });
187→
188→    [button, text].forEach((element) => {
189→      element.on('pointerover', () => {
190→        button.setFillStyle(0xffff99);
191→      });
192→
193→      element.on('pointerout', () => {
194→        button.setFillStyle(0xffffff);
195→      });
196→
197→      element.on('pointerdown', () => {
198→        this.scene.start('ModeSelectScene');
199→      });
200→    });
201→  }
202→}
