  1→/**
  2→ * 똥(장애물) 설정
  3→ *
  4→ * 모든 똥 오브젝트(일반, 금똥, 다이아똥, 토파즈똥)의 크기, 속도, 히트박스 등을 관리합니다.
  5→ * 게임 밸런싱 조정 시 이 파일만 수정하면 됩니다.
  6→ */
  7→
  8→export interface PoopConfig {
  9→  /** 일반 똥 설정 */
 10→  normal: {
 11→    /** 기본 낙하 속도 */
 12→    baseSpeed: number;
 13→    /** 난이도 레벨당 속도 증가량 */
 14→    speedIncrement: number;
 15→    /** 일반 똥 크기 */
 16→    size: {
 17→      /** 기본 크기 */
 18→      normal: number;
 19→      /** EXTREME 난이도 크기 */
 20→      extreme: number;
 21→    };
 22→    /** 크리스마스 특수 똥 크기 (코, 리본, 산타, 수염) */
 23→    specialSize: {
 24→      /** 기본 크기 */
 25→      normal: number;
 26→      /** EXTREME 난이도 크기 */
 27→      extreme: number;
 28→    };
 29→    /** 히트박스 크기 */
 30→    hitbox: {
 31→      /** 기본 히트박스 */
 32→      normal: number;
 33→      /** EXTREME 난이도 히트박스 */
 34→      extreme: number;
