 1→import Phaser from 'phaser';
 2→import ModeSelectScene from './scenes/ModeSelectScene';
 3→import DifficultySelectScene from './scenes/DifficultySelectScene';
 4→import GameScene from './scenes/GameScene';
 5→import LeaderboardScene from './scenes/LeaderboardScene';
 6→import ReleaseNotesScene from './scenes/ReleaseNotesScene';
 7→import { ensureLoggedIn } from './utils/auth';
 8→import './style.css';
 9→
10→const config: Phaser.Types.Core.GameConfig = {
11→  type: Phaser.AUTO,
12→  width: 400,
13→  height: 600,
14→  parent: 'game-container',
15→  backgroundColor: '#87CEEB',
16→  physics: {
17→    default: 'arcade',
18→    arcade: {
19→      gravity: { y: 0, x: 0 },
20→      debug: false,
21→      fixedStep: false
22→    }
23→  },
24→  scene: [ModeSelectScene, DifficultySelectScene, GameScene, LeaderboardScene, ReleaseNotesScene],
25→  scale: {
26→    mode: Phaser.Scale.FIT,
27→    autoCenter: Phaser.Scale.CENTER_BOTH
28→  },
29→  render: {
30→    antialias: true,
31→    roundPixels: false
32→  },
33→  fps: {
